def compare_semver(v1: str, v2: str) -> int:
    def parse(v):
        # Strip build metadata (after '+') if present
        if '+' in v:
            v = v.split('+', 1)[0]
        # Split off prerelease (after first '-')
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None
        parts = core.split('.')
        nums = [int(p) for p in parts]
        # Pad to exactly three components (missing components are 0)
        while len(nums) < 3:
            nums.append(0)
        return nums, pre

    def cmp_prerelease(p1, p2):
        # None means release (no prerelease)
        if p1 is None and p2 is None:
            return 0
        if p1 is None:
            return 1
        if p2 is None:
            return -1
        ids1 = p1.split('.')
        ids2 = p2.split('.')
        n = max(len(ids1), len(ids2))
        for i in range(n):
            a = ids1[i] if i < len(ids1) else None
            b = ids2[i] if i < len(ids2) else None
            if a is None and b is None:
                continue
            if a is None:
                # fewer identifiers -> lower precedence
                return -1
            if b is None:
                return 1
            # both present
            a_num = a.isdigit()
            b_num = b.isdigit()
            if a_num and b_num:
                ia, ib = int(a), int(b)
                if ia < ib:
                    return -1
                if ia > ib:
                    return 1
            elif a_num:
                # numeric < alphanumeric
                return -1
            elif b_num:
                return 1
            else:
                # both alphanumeric, compare lexicographically (ASCII)
                if a < b:
                    return -1
                if a > b:
                    return 1
        return 0

    n1, p1 = parse(v1)
    n2, p2 = parse(v2)
    for i in range(3):
        if n1[i] < n2[i]:
            return -1
        if n1[i] > n2[i]:
            return 1
    return cmp_prerelease(p1, p2)
